<template>
  <div class="textTask">
    <div class="formatted-text">
      <span 
        v-for="(word, wordIndex) in formattedText" 
        :key="wordIndex"
        :data-sentence="word.sentence"
        :data-word="word.word"
        class="word-block"
      >
        <span 
          v-for="(letter, letterIndex) in word.letters" 
          :key="letterIndex"
          :data-letter-position="letter.letterPosition"
          class="letter"
        >
          {{ letter.char }}
        </span>
        <!-- Add space only if the next item is a word (not punctuation) -->
        <span 
          v-if="wordIndex < formattedText.length - 1 && formattedText[wordIndex + 1].isWord" 
          class="space"
        ></span>
      </span>
    </div>
  </div>
</template>

<script>
export default {
  name: 'textTask',
  props: {
    msg: String
  },
  computed: {
    formattedText() {
      const text = `Twas brillig, and the slithy toves
      Did gyre and gimble in the wabe:
All mimsy were the borogoves,
      And the mome raths outgrabe.

“Beware the Jabberwock, my son!
      The jaws that bite, the claws that catch!
Beware the Jubjub bird, and shun
      The frumious Bandersnatch!”

He took his vorpal sword in hand;
      Long time the manxome foe he sought—
So rested he by the Tumtum tree
      And stood awhile in thought.

And, as in uffish thought he stood,
      The Jabberwock, with eyes of flame,
Came whiffling through the tulgey wood,
      And burbled as it came!

One, two! One, two! And through and through
      The vorpal blade went snicker-snack!
He left it dead, and with its head
      He went galumphing back.

“And hast thou slain the Jabberwock?
      Come to my arms, my beamish boy!
O frabjous day! Callooh! Callay!”
      He chortled in his joy.

’Twas brillig, and the slithy toves
      Did gyre and gimble in the wabe:
All mimsy were the borogoves,
      And the mome raths outgrabe.`;

      let sentenceCount = 1;
      let wordCount = 1;
      let formattedArray = [];

      // Match words (including apostrophes) and punctuation, keeping them together
      let words = text.match(/[\w’]+[.,!?;:"]*|[.,!?;:"]+/g);

      words.forEach((word) => {
        let isWord = /\w/.test(word); // Check if it's an actual word
        let isLastInSentence = /[.!?]$/.test(word); // Check if it ends a sentence
        
        let letters = word.split('').map((char, i) => ({
          char,
          letterPosition: i + 1
        }));

        formattedArray.push({
          sentence: sentenceCount,
          word: isWord ? wordCount : null,
          letters,
          isWord
        });

        if (isWord) {
          wordCount++; // Only count actual words, not punctuation
        }

        if (isLastInSentence) {
          sentenceCount++; // Increment sentence count after sentence-ending punctuation
        }
      });

      return formattedArray;
    }
  }
};
</script>

