<template>
  <div class="textTask">
    <div class="formatted-text">
      <span 
        v-for="(word, wordIndex) in formattedText" 
        :key="wordIndex"
        :data-sentence="word.sentence"
        :data-word="word.word"
        class="word-block"
      >
        <span 
          v-for="(letter, letterIndex) in word.letters" 
          :key="letterIndex"
          :data-letter-position="letter.letterPosition"
          class="letter"
        >
          {{ letter.char }}
        </span>
        <!-- Add space only if the next item is a word (not punctuation) -->
        <span 
          v-if="wordIndex < formattedText.length - 1 && formattedText[wordIndex + 1].isWord" 
          class="space"
        ></span>
      </span>
    </div>
  </div>
</template>

<script>
export default {
  name: 'textTask',
  props: {
    msg: String
  },
  computed: {
    formattedText() {
      const text = ` As soon as she had made out the proper way of nursing it, (which was to twist it up into a sort of knot, and then keep tight hold of its right ear and left foot, so as to prevent its undoing itself,) she carried it out into the open air. “If I don’t take this child away with me,” thought Alice, “they’re sure to kill it in a day or two: wouldn’t it be murder to leave it behind?” She said the last words out loud, and the little thing grunted in reply (it had left off sneezing by this time). “Don’t grunt,” said Alice; “that’s not at all a proper way of expressing yourself.”

The baby grunted again, and Alice looked very anxiously into its face to see what was the matter with it. There could be no doubt that it had a very turn-up nose, much more like a snout than a real nose; also its eyes were getting extremely small for a baby: altogether Alice did not like the look of the thing at all. “But perhaps it was only sobbing,” she thought, and looked into its eyes again, to see if there were any tears.

No, there were no tears. “If you’re going to turn into a pig, my dear,” said Alice, seriously, “I’ll have nothing more to do with you. Mind now!” The poor little thing sobbed again (or grunted, it was impossible to say which), and they went on for some while in silence.

Alice was just beginning to think to herself, “Now, what am I to do with this creature when I get it home?” when it grunted again, so violently, that she looked down into its face in some alarm. This time there could be no mistake about it: it was neither more nor less than a pig, and she felt that it would be quite absurd for her to carry it further.

So she set the little creature down, and felt quite relieved to see it trot away quietly into the wood. “If it had grown up,” she said to herself, “it would have made a dreadfully ugly child: but it makes rather a handsome pig, I think.” And she began thinking over other children she knew, who might do very well as pigs, and was just saying to herself, “if one only knew the right way to change them—” when she was a little startled by seeing the Cheshire Cat sitting on a bough of a tree a few yards off. 
`;

      let sentenceCount = 1;
      let wordCount = 1;
      let formattedArray = [];

      // Match words (including apostrophes) and punctuation, keeping them together
      let words = text.match(/[\w’]+[.,!?;:"]*|[.,!?;:"]+/g);

      words.forEach((word) => {
        let isWord = /\w/.test(word); // Check if it's an actual word
        let isLastInSentence = /[.!?]$/.test(word); // Check if it ends a sentence
        
        let letters = word.split('').map((char, i) => ({
          char,
          letterPosition: i + 1
        }));

        formattedArray.push({
          sentence: sentenceCount,
          word: isWord ? wordCount : null,
          letters,
          isWord
        });

        if (isWord) {
          wordCount++; // Only count actual words, not punctuation
        }

        if (isLastInSentence) {
          sentenceCount++; // Increment sentence count after sentence-ending punctuation
        }
      });

      return formattedArray;
    }
  }
};
</script>

<style scoped>
.textTask {
  text-align: center;
  font-family: Arial, sans-serif;
}

h3 {
  margin: 40px 25% 0;
}

.formatted-text {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  text-align: justify;
  margin: 40px auto;
  max-width: 33%; /* Using only the middle 1/3 of the screen */
  width: 100%;
}

.word-block {
  display: inline-flex; /* Allow words to be treated as a single block */
  flex-wrap: nowrap;
}

.letter {
  font-size: 18px; /* Standard font size */
}

.space {
  width: 4px; /* Tiny space between words */
}
</style>
