<template>
  <div class="container">
  <p v-if="trial === 25">Completed, please move onto the next task!</p>
    <div class="grid"  :style="[gridStyle,{
        '--horizontal-padding':  '100vw',
        '--vertical-padding': '20vh'
      }]">
      <img
        v-for="(image, index) in grid"
        :key="index"
        :src="image.src"
        @click="handleClick(index)"
        class="grid-item"
        :data-id="image.id"
        :data-correct="image.isCorrect ? 'T' : 'F'"
        :style="gridItemStyle"
        alt="Game Image"
      />
    </div>
  </div>
</template>

<script>
import { ref, computed, onMounted, watch } from "vue";

// Load images using Webpack's require.context()
const requireSetB = require.context("@/assets/images/Wrong", false, /.*\.jpg$/);
const requireSetA = require.context("@/assets/images/Right", false, /.*\.jpg$/);

const allSetA = requireSetA.keys().map((img, index) => ({
  src: requireSetA(img),
  id: index + 1,
}));

const setB = requireSetB.keys().map((img, index) => ({
  src: requireSetB(img),
  id: allSetA.length + index + 1,
}));

export default {
  setup() {
    const gridSize = ref(3); // Change this to 2, 3, or 4
    const grid = ref([]);
    const trial = ref(0);
    const score = ref(0);
    let replacedIndex = ref(null);
    gridSize.value = 2;
    const getRandomSubset = (array, size) => {
      return [...array].sort(() => Math.random() - 0.5).slice(0, size);
    };

    const generateGrid = () => {
      const totalCells = gridSize.value ** 2;

      let newGrid = getRandomSubset(allSetA, totalCells).map((img, i) => ({
        ...img,
        id: i + 1,
        isCorrect: false,
      }));

      replacedIndex.value = Math.floor(Math.random() * totalCells);
      let randomBImage = {
        ...setB[Math.floor(Math.random() * setB.length)],
        id: replacedIndex.value + 1,
        isCorrect: true,
      };

      newGrid[replacedIndex.value] = randomBImage;
      grid.value = newGrid;
    };

    const handleClick = (index) => {
      if (trial.value >= 25) return;
      if (grid.value[index].isCorrect) score.value++;
      trial.value++;
      if (trial.value < 25) generateGrid();
    };

    watch(gridSize, generateGrid);
    onMounted(generateGrid);

    return {
      gridSize, // Now you can change this directly in the script
      grid,
      trial,
      score,
      handleClick,
      gridStyle: computed(() => ({
        display: "grid",
        gridTemplateColumns: `repeat(${gridSize.value}, 1fr)`,
        gridTemplateRows: `repeat(${gridSize.value}, 1fr)`,
        gap: `${5 - gridSize.value}vw`, // Adjusts spacing dynamically
        width: "70vh",
        height: "70vh",
      })),
      gridItemStyle: computed(() => ({
        width: `calc(70vh / ${gridSize.value + 1})`,
        height: `calc(70vh / ${gridSize.value + 1})`,
      })),
    };
  },
};
</script>

<style scoped>
.container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100vh;
  width: 100vw;
  overflow: hidden;
}

.grid-item {
  object-fit: cover;
  cursor: pointer;
  border: 2px solid transparent;
  transition: 0.3s;
}

.grid-item:hover {
  border-color: #3498db;
}
</style>
