<template>
  <div class="container">
    <h2>Demographic Information</h2>
    <form @submit.prevent="submitForm">
      <label>
        ID:
        <input type="number" v-model="formData.ID" required />
      </label>

      <label>
        Age:
        <input type="number" v-model="formData.age" required />
      </label>

      <label>
        Gender:
        <select v-model="formData.gender" required>
          <option value="" disabled>Select</option>
          <option value="Male">Male</option>
          <option value="Female">Female</option>
          <option value="Other">Other</option>
        </select>
      </label>

      <label>
        Major/Occupation:
        <input type="text" v-model="formData.Major" required />
      </label>

      <button type="submit">Submit</button>
    </form>

    <p v-if="message" class="message">{{ message }}</p>
  </div>
</template>

<script>
import Papa from "papaparse";

export default {
  data() {
    return {
      formData: {
        name: "",
        age: "",
        gender: "",
        country: "",
      },
      message: "",
    };
  },
  methods: {
    async submitForm() {
      const newRow = [this.formData.name, this.formData.age, this.formData.gender, this.formData.country];

      try {
        let fileHandle = await window.showOpenFilePicker({
          types: [{ description: "CSV Files", accept: { "text/csv": [".csv"] } }],
        });

        fileHandle = await fileHandle[0].getFile();
        let fileContents = await fileHandle.text();

        // Parse existing CSV
        let csvData = Papa.parse(fileContents, { skipEmptyLines: true }).data;
        csvData.push(newRow); // Append new data

        const updatedCSV = Papa.unparse(csvData);
        const writable = await (await fileHandle.createWritable()).write(updatedCSV);
        await writable.close();

        this.message = "Data successfully saved!";
        this.resetForm();
      } catch (error) {
        console.error("Error handling file:", error);
        this.message = "Failed to save data. Ensure you select the correct file.";
      }
    },
    resetForm() {
      this.formData = { name: "", age: "", gender: "", country: "" };
    },
  },
};
</script>

