<template>
  <div class="textTask">
    <div class="formatted-text">
      <span 
        v-for="(word, wordIndex) in formattedText" 
        :key="wordIndex"
        :data-sentence="word.sentence"
        :data-word="word.word"
        class="word-block"
      >
        <span 
          v-for="(letter, letterIndex) in word.letters" 
          :key="letterIndex"
          :data-letter-position="letter.letterPosition"
          class="letter"
        >
          {{ letter.char }}
        </span>
        <!-- Add space only if the next item is a word (not punctuation) -->
        <span 
          v-if="wordIndex < formattedText.length - 1 && formattedText[wordIndex + 1].isWord" 
          class="space"
        ></span>
      </span>
    </div>
  </div>
</template>

<script>
export default {
  name: 'textTask',
  props: {
    msg: String
  },
  computed: {
    formattedText() {
      const text = ` This time Alice waited patiently until it chose to speak again. In a minute or two the Caterpillar took the hookah out of its mouth and yawned once or twice, and shook itself. Then it got down off the mushroom, and crawled away in the grass, merely remarking as it went, “One side will make you grow taller, and the other side will make you grow shorter.”

“One side of what? The other side of what?” thought Alice to herself.

“Of the mushroom,” said the Caterpillar, just as if she had asked it aloud; and in another moment it was out of sight.

Alice remained looking thoughtfully at the mushroom for a minute, trying to make out which were the two sides of it; and as it was perfectly round, she found this a very difficult question. However, at last she stretched her arms round it as far as they would go, and broke off a bit of the edge with each hand.

“And now which is which?” she said to herself, and nibbled a little of the right-hand bit to try the effect: the next moment she felt a violent blow underneath her chin: it had struck her foot!

She was a good deal frightened by this very sudden change, but she felt that there was no time to be lost, as she was shrinking rapidly; so she set to work at once to eat some of the other bit. Her chin was pressed so closely against her foot, that there was hardly room to open her mouth; but she did it at last, and managed to swallow a morsel of the lefthand bit. `;

      let sentenceCount = 1;
      let wordCount = 1;
      let formattedArray = [];

      // Match words (including apostrophes) and punctuation, keeping them together
      let words = text.match(/[\w’]+[.,!?;:"]*|[.,!?;:"]+/g);

      words.forEach((word) => {
        let isWord = /\w/.test(word); // Check if it's an actual word
        let isLastInSentence = /[.!?]$/.test(word); // Check if it ends a sentence
        
        let letters = word.split('').map((char, i) => ({
          char,
          letterPosition: i + 1
        }));

        formattedArray.push({
          sentence: sentenceCount,
          word: isWord ? wordCount : null,
          letters,
          isWord
        });

        if (isWord) {
          wordCount++; // Only count actual words, not punctuation
        }

        if (isLastInSentence) {
          sentenceCount++; // Increment sentence count after sentence-ending punctuation
        }
      });

      return formattedArray;
    }
  }
};
</script>

