  max-width: 33%; /* Using only the middle 1/3 of the screen */
  width: 100%;
}

.word-block {
  display: inline-flex; /* Allow words to be treated as a single block */
  flex-wrap: nowrap;
}

.letter {
  font-size: 18px; /* Standard font size */
}

.space {
  width: 4px; /* Tiny space between words */
}
</style>
